INSERT INTO `questions` VALUES (56,9,'Qu\'est-ce qu\'Azure Key Vault ?','qcm',0.50,1,NULL,NULL),(57,9,'Quels sont les trois principaux types d\'objets gérés par Azure Key Vault ?','qcm',0.50,2,NULL,NULL),(58,9,'Quelle commande Azure CLI permet de créer un nouveau Key Vault ?','qcm',0.50,3,NULL,NULL),(59,9,'Quelle commande Azure CLI permet de stocker un secret dans un Key Vault existant ?','qcm',0.50,4,NULL,NULL),(60,9,'Quelle cmdlet PowerShell permet de récupérer un secret depuis Azure Key Vault ?','qcm',0.50,5,NULL,NULL),(61,9,'Quel mécanisme de contrôle d\'accès est recommandé par Microsoft pour gérer les permissions sur Azure Key Vault ?','qcm',0.50,6,NULL,NULL),(62,9,'Quelle est la différence principale entre les niveaux de tarification « Standard » et « Premium » d\'Azure Key Vault ?','qcm',0.50,7,NULL,NULL),(63,9,'Qu\'est-ce que la fonctionnalité « Soft Delete » (suppression réversible) dans Azure Key Vault ?','qcm',0.50,8,NULL,NULL),(64,9,'Quelle commande PowerShell permet de créer un Azure Key Vault avec la protection contre la purge activée ?','qcm',0.50,9,NULL,NULL),(65,9,'Vous souhaitez autoriser une application à accéder aux secrets d\'un Key Vault en utilisant Azure RBAC. Quel rôle intégré devez-vous attribuer au principal de service de l\'application pour qu\'il puisse uniquement lire les secrets, sans les modifier ?','qcm',0.50,10,NULL,NULL),(66,9,'Qu\'est-ce qu\'un Network Security Group (NSG) dans Azure ?','qcm',0.50,11,NULL,NULL),(67,9,'À quelle(s) ressource(s) peut-on associer un NSG dans Azure ?','qcm',0.50,12,NULL,NULL),(68,9,'Pour le trafic ENTRANT vers une VM, dans quel ordre les NSG sont-ils évalués si un NSG est associé au sous-réseau ET à la NIC ?','qcm',0.50,13,NULL,NULL),(69,9,'Quelle commande Azure CLI crée un NSG nommé \"MonNSG\" dans le groupe de ressources \"MonRG\" ?','qcm',0.50,14,NULL,NULL),(70,9,'Combien de règles par défaut (default security rules) contient un NSG nouvellement créé dans Azure ?','qcm',0.50,15,NULL,NULL),(71,9,'Qu